1	import { afterAll, beforeEach, describe, expect, it } from 'vitest';
2	import { createApp } from '../src/app.ts';
3	import { createServices } from '../src/container.ts';
4	import { readEnv } from '../src/env.ts';
5	import { createPropertyRepository } from '../src/repositories/property.repository.ts';
6	import { createPropertyService } from '../src/services/create-property.service.ts';
7	import { deletePropertyService } from '../src/services/delete-property.service.ts';
8	import { getPropertyService } from '../src/services/get-property.service.ts';
9	import { listPropertiesService } from '../src/services/list-properties.service.ts';
10	import { createWeatherstackClient } from '../src/weatherstack/client.ts';
11	import { resetTables, testPrisma } from './database.ts';
12	import { executeOperation } from './graphql.ts';
13	import { server } from './msw.ts';
14	import { TEST_ACCESS_KEY, weatherstack } from './weatherstack.ts';
15	
16	const properties = createPropertyRepository(testPrisma);
17	const app = createApp({
18	  services: {
19	    listProperties: listPropertiesService({ properties }),
20	    getProperty: getPropertyService({ properties }),
21	    deleteProperty: deletePropertyService({ properties }),
22	    createProperty: createPropertyService({
23	      properties,
24	      weatherstack: createWeatherstackClient({
25	        baseUrl: 'http://weatherstack.test',
26	        accessKey: TEST_ACCESS_KEY,
27	        timeoutMs: 100,
28	      }),
29	      logger: { warn: () => {} },
30	    }),
31	  },
32	});
33	
34	const CREATE = /* GraphQL */ `
35	  mutation Create($input: CreatePropertyInput!) {
36	    createProperty(input: $input) {
37	      __typename
38	      ... on CreatePropertySuccess {
39	        property {
40	          id
41	          street
42	          city
43	          state
44	          zipCode
45	          lat
46	          long
47	          createdAt
48	          weatherData {
49	            observationTime
50	            temperature
51	            feelsLike
52	            weatherCode
53	            weatherDescriptions
54	            weatherIcons
55	            humidity
56	            windSpeed
57	            windDegree
58	            windDir
59	            pressure
60	            precip
61	            cloudcover
62	            uvIndex
63	            visibility
64	            isDay
65	          }
66	        }
67	      }
68	      ... on InvalidInputError {
69	        message
70	        fieldErrors {
71	          field
72	          message
73	        }
74	      }
75	      ... on DuplicatePropertyError {
76	        message
77	        existingPropertyId
78	      }
79	      ... on WeatherUnavailableError {
80	        message
81	        reason
82	      }
83	    }
84	  }
85	`;
86	
87	const INPUT = {
88	  street: '15528 E Golden Eagle Blvd',
89	  city: 'Fountain Hills',
90	  state: 'AZ',
91	  zipCode: '85268',
92	};
93	
94	/** The `createProperty` payload as selected by CREATE; union members leave the others undefined. */
95	interface CreatePropertyPayload {
96	  __typename: string;
97	  property: { id: string; createdAt: string; weatherData: unknown } & Record<string, unknown>;
98	  message: string;
99	  reason: string;
100	}
101	
102	const execute = (
103	  query: string,
104	  variables: Record<string, unknown>,
105	  target: ReturnType<typeof createApp> = app,
106	) => executeOperation<{ createProperty: CreatePropertyPayload }>(target, query, variables);
107	
108	const create = (input: Record<string, unknown> = INPUT) => execute(CREATE, { input });
109	
110	describe('createProperty (GraphQL → Postgres)', () => {
111	  beforeEach(resetTables);
112	  afterAll(() => testPrisma.$disconnect());
113	
114	  it('S5.1 creates the property with weather, lat and long from one Weatherstack call', async () => {
115	    const requests: URL[] = [];
116	    server.use(weatherstack.ok(requests));
117	
118	    const { body } = await create();
119	
120	    expect(requests).toHaveLength(1);
121	    const result = body.data!.createProperty;
122	    expect(result.__typename).toBe('CreatePropertySuccess');
123	    expect(result.property).toMatchObject({ ...INPUT, lat: 33.609, long: -111.729 });
124	    expect(new Date(result.property.createdAt).toISOString()).toBe(result.property.createdAt);
125	    expect(await testPrisma.property.count()).toBe(1);
126	  });
127	
128	  it('S7.2 exposes every Weather field mapped from the stored Weatherstack object', async () => {
129	    server.use(weatherstack.ok());
130	
131	    const { body } = await create();
132	
133	    expect(body.data!.createProperty.property.weatherData).toEqual({
134	      observationTime: '10:35 AM',
135	      temperature: 79,
136	      feelsLike: 79,
137	      weatherCode: 122,
138	      weatherDescriptions: ['Overcast'],
139	      weatherIcons: [
140	        'https://cdn.worldweatheronline.com/images/wsymbols01_png_64/wsymbol_0004_black_low_cloud.png',
141	      ],
