// Local stand-in for Weatherstack so the running app never spends real API calls.
//   node e2e/weatherstack-stub.mjs            → serves the recorded Fountain Hills response
//   STUB_MODE=success-false node e2e/…       → HTTP 200 { success: false } (UPSTREAM_ERROR)
// In the default mode, zip code FAILING_ZIP also gets { success: false }, so e2e can exercise the
// failure path (SPEC X4) against the same running stack.
// Point the API at it with WEATHERSTACK_BASE_URL=http://localhost:4999.
import { readFileSync } from 'node:fs';
import { createServer } from 'node:http';

export const FAILING_ZIP = '00000';

const port = Number(process.env.WEATHERSTACK_STUB_PORT ?? 4999);
const mode = process.env.STUB_MODE ?? 'ok';
const fixture = readFileSync(
  new URL('../../api/test/fixtures/weatherstack-current.json', import.meta.url),
  'utf8',
);
const failure = JSON.stringify({
  success: false,
  error: { code: 104, type: 'usage_limit_reached', info: 'Stubbed failure.' },
});

createServer((request, response) => {
  const url = new URL(request.url ?? '/', 'http://stub');
  if (url.pathname !== '/current') {
    response.writeHead(404).end();
    return;
  }
  const fails =
    mode === 'success-false' || url.searchParams.get('query')?.startsWith(`${FAILING_ZIP},`);
  response.writeHead(200, { 'content-type': 'application/json' });
  response.end(fails ? failure : fixture);
}).listen(port, () => console.info(`Weatherstack stub (${mode}) on http://localhost:${port}`));

import { useQuery } from '@apollo/client/react';
import { Link, useLocation, useSearchParams } from 'react-router';
import { ArrowDownUp } from 'lucide-react';
import { Alert, AlertDescription, AlertTitle } from '@/components/ui/alert';
import { Button } from '@/components/ui/button';
import { Card, CardContent } from '@/components/ui/card';
import { Skeleton } from '@/components/ui/skeleton';
import { SortDirection, type PropertiesQuery as PropertiesResult } from '@/gql/graphql';
import { readListParams, writeListParams, type ListLocationState } from './list-search-params';
import { PropertiesQuery } from './properties.query';
import {
  isFiltering,
  NO_FILTER,
  PropertyFilters,
  toPropertyFilter,
  type FilterValues,
} from './property-filters';

type Property = PropertiesResult['properties'][number];

const SORT_LABEL: Record<SortDirection, string> = {
  DESC: 'Newest first',
  ASC: 'Oldest first',
};

const createdAtFormat = new Intl.DateTimeFormat('en-US', {
  dateStyle: 'medium',
  timeStyle: 'short',
});

/** S1 list with the S2 sort toggle and S3 filters, both kept in the URL. */
export function PropertyList() {
  const [searchParams, setSearchParams] = useSearchParams();
  const { filter, direction } = readListParams(searchParams);
  const setFilter = (next: FilterValues) =>
    setSearchParams(writeListParams({ filter: next, direction }));
  const setDirection = (next: SortDirection) =>
    setSearchParams(writeListParams({ filter, direction: next }), { replace: true });
  const { data, error, loading, refetch } = useQuery(PropertiesQuery, {
    variables: { filter: toPropertyFilter(filter), orderBy: { createdAt: direction } },
    // The list is unmounted while a property is created, so a named refetch would miss it.
    // Showing the cache and re-fetching on every mount keeps it current (S5.8).
    fetchPolicy: 'cache-and-network',
  });
  const properties = data?.properties;

  return (
    <section className="grid gap-4">
      <div className="flex items-center justify-between gap-4">
        <h1 className="font-heading text-2xl font-semibold">Properties</h1>
        <Button
          variant="outline"
          size="sm"
          onClick={() =>
            setDirection(direction === SortDirection.DESC ? SortDirection.ASC : SortDirection.DESC)
          }
          aria-label={`Sorted by creation date: ${SORT_LABEL[direction]}. Change order`}
        >
          <ArrowDownUp />
          {SORT_LABEL[direction]}
        </Button>
      </div>

      <PropertyFilters applied={filter} onApply={setFilter} />

      {error && !properties ? (
        <Alert variant="destructive">
          <AlertTitle>Could not load properties</AlertTitle>
          <AlertDescription className="grid gap-2">
            <span>Check that the API is running, then try again.</span>
            <Button
              variant="outline"
              size="sm"
              className="justify-self-start"
              onClick={() => void refetch()}
            >
              Retry
            </Button>
          </AlertDescription>
        </Alert>
      ) : !properties && loading ? (
        <PropertyListSkeleton />
      ) : properties?.length === 0 && isFiltering(filter) ? (
        <Card>
          <CardContent className="grid justify-items-center gap-2 py-8 text-center">
            <p className="font-medium">No properties match these filters</p>
            <Button variant="outline" size="sm" onClick={() => setFilter(NO_FILTER)}>
              Clear filters
            </Button>
          </CardContent>
        </Card>
      ) : properties?.length === 0 ? (
        <Card>
          <CardContent className="grid gap-2 py-8 text-center">
            <p className="font-medium">No properties yet</p>
            <p className="text-muted-foreground">
              <Link to="/properties/new" className="underline">
                Add a property
              </Link>{' '}
              to record it with its current weather.
            </p>
          </CardContent>
        </Card>
      ) : (
        <ul className="grid gap-3" aria-label="Properties">
          {properties?.map((property) => (
            <li key={property.id}>
              <PropertyRow property={property} />
            </li>
          ))}
        </ul>
      )}
    </section>
  );
}

function PropertyListSkeleton() {
  return (
    <div className="grid gap-3" role="status" aria-label="Loading properties">
      {[0, 1, 2].map((row) => (
        <div
          key={row}
          className="flex items-center justify-between gap-4 rounded-xl p-4 ring-1 ring-foreground/10"
        >
          <div className="grid gap-1.5">
            <Skeleton className="h-4 w-48" />
            <Skeleton className="h-3 w-36" />
            <Skeleton className="h-3 w-28" />
          </div>
          <div className="flex items-center gap-2">
            <Skeleton className="size-8" />
            <Skeleton className="h-8 w-16" />
          </div>
        </div>
      ))}
    </div>
  );
}

function PropertyRow({ property }: { property: Property }) {
  const { search } = useLocation();
  const description = property.weatherData.weatherDescriptions.join(', ');
  const icon = property.weatherData.weatherIcons[0];
  return (
    <Link
      to={`/properties/${property.id}`}
      state={{ listSearch: search } satisfies ListLocationState}
      className="block rounded-xl ring-1 ring-foreground/10 transition-colors hover:bg-muted/50 focus-visible:outline-2"
    >
      <div className="flex items-center justify-between gap-4 p-4">
        <div className="grid gap-0.5">
          <span className="font-medium">{property.street}</span>
          <span className="text-sm text-muted-foreground">
            {property.city}, {property.state} {property.zipCode}
          </span>
          <span className="text-xs text-muted-foreground">
            Added {createdAtFormat.format(new Date(property.createdAt))}
          </span>
        </div>
        <div className="flex items-center gap-2 text-right">
          {icon && <img src={icon} alt="" className="size-8 rounded" />}
          <div className="grid">
            <span className="font-medium">{property.weatherData.temperature}°F</span>
            <span className="text-xs text-muted-foreground">{description}</span>
          </div>
        </div>
      </div>
    </Link>
  );
}

