33	/** A tiny stand-in for the server's S3 semantics, recording every request's variables. */
34	function serveFiltered(calls: PropertiesQueryVariables[]) {
35	  return graphql.query<PropertiesQuery, PropertiesQueryVariables>('Properties', ({ variables }) => {
36	    calls.push(variables);
37	    const f = variables.filter ?? {};
38	    const rows = ROWS.filter(
