40	        (!f.city || p.city.toLowerCase().includes(f.city.toLowerCase())) &&
41	        (!f.zipCode || p.zipCode === f.zipCode) &&
42	        (!f.state || p.state === f.state),
43	    );
44	    return HttpResponse.json({ data: { __typename: 'Query', properties: rows } });
45	  });
46	}
