13	function respondWith(result: Result, calls: CreatePropertyMutationVariables[] = [], wait = 0) {
14	  return graphql.mutation<CreatePropertyMutation, CreatePropertyMutationVariables>(
15	    'CreateProperty',
16	    async ({ variables }) => {
17	      calls.push(variables);
18	      if (wait) await delay(wait);
