81	
82	  it('S5.8 sends the input and navigates to the new property on success', async () => {
83	    const calls: CreatePropertyMutationVariables[] = [];
84	    server.use(
85	      respondWith(SUCCESS, calls),
86	      serveProperty([detailedProperty({ id: 'new-id', street: '15528 E Golden Eagle Blvd' })]),
87	    );
88	    const { submit } = await fillForm();
89	
90	    await submit();
91	
92	    expect(
93	      await screen.findByRole('heading', { name: '15528 E Golden Eagle Blvd' }),
94	    ).toBeInTheDocument();
95	    expect(screen.getByText('Property created')).toBeInTheDocument();
96	    expect(calls).toEqual([
97	      {
98	        input: {
99	          street: '15528 E Golden Eagle Blvd',
100	          city: 'Fountain Hills',
101	          state: 'AZ',
102	          zipCode: '85268',
103	        },
104	      },
105	    ]);
106	  });
107	
108	  it('S5.8 shows server field errors next to the field', async () => {
109	    server.use(
110	      respondWith({
111	        __typename: 'InvalidInputError',
112	        message: 'Some fields are invalid.',
113	        fieldErrors: [
114	          {
115	            __typename: 'FieldError',
116	            field: 'city',
117	            message: 'City must be at most 100 characters.',
118	          },
119	        ],
120	      }),
121	    );
