import type { CodegenConfig } from '@graphql-codegen/cli';

const config: CodegenConfig = {
  schema: 'src/schema.graphql',
  generates: {
    'src/__generated__/resolvers-types.ts': {
      plugins: ['typescript', 'typescript-resolvers'],
      config: {
        useTypeImports: true,
        // String unions are structurally identical to Prisma's USState, so no enum mapping is needed.
        enumsAsTypes: true,
        contextType: '../context.ts#Context',
        mapperTypeSuffix: 'Model',
        mappers: {
          Property: './prisma/client.ts#Property',
          Weather: '../weatherstack/schema.ts#WeatherstackCurrent',
        },
        scalars: {
          DateTime: { input: 'Date', output: 'Date | string' },
        },
        resolversNonOptionalTypename: { unionMember: true },
      },
    },
  },
};

export default config;

import type { CodegenConfig } from '@graphql-codegen/cli';

const config: CodegenConfig = {
  schema: '../api/src/schema.graphql',
  documents: ['src/**/*.{ts,tsx}', '!src/gql/**'],
  ignoreNoDocuments: true,
  generates: {
    'src/gql/': {
      preset: 'client',
      presetConfig: { fragmentMasking: false },
      config: {
        useTypeImports: true,
        // Runtime object for the state <select>, generated from the schema rather than duplicated.
        enumType: 'const',
        namingConvention: 'keep',
        scalars: { DateTime: 'string' },
        // Apollo adds __typename to every selection; types (and test mocks) should match responses.
        nonOptionalTypename: true,
      },
    },
  },
};

export default config;

import { graphql, HttpResponse } from 'msw';
import type { PropertyQuery, PropertyQueryVariables } from '@/gql/graphql';

export type DetailedProperty = NonNullable<PropertyQuery['property']>;

/** A property as the detail query returns it, using the recorded Fountain Hills weather. */
export function detailedProperty(overrides: Partial<DetailedProperty> = {}): DetailedProperty {
  return {
    __typename: 'Property',
    id: 'property-1',
    street: '15528 E Golden Eagle Blvd',
    city: 'Fountain Hills',
    state: 'AZ',
    zipCode: '85268',
    lat: 33.609,
    long: -111.729,
    createdAt: '2026-09-24T10:53:08.106Z',
    weatherData: {
      __typename: 'Weather',
      observationTime: '10:35 AM',
      temperature: 79,
      feelsLike: 81,
      weatherDescriptions: ['Overcast'],
      weatherIcons: ['https://cdn.example/overcast.png'],
      humidity: 42,
      windSpeed: 6,
      windDir: 'NE',
    },
    ...overrides,
  };
}

/** Answers the Property query from `rows` by id; unknown ids get `null` (S4.2). */
export function serveProperty(rows: DetailedProperty[]) {
  return graphql.query<PropertyQuery, PropertyQueryVariables>('Property', ({ variables }) =>
    HttpResponse.json({
      data: {
        __typename: 'Query',
        property: rows.find((row) => row.id === variables.id) ?? null,
      },
    }),
  );
}

