import { graphql } from '@/gql';

export const DeletePropertyMutation = graphql(`
  mutation DeleteProperty($id: ID!) {
    deleteProperty(id: $id) {
      __typename
      ... on DeletePropertySuccess {
        id
      }
      ... on PropertyNotFoundError {
        message
        id
      }
    }
  }
`);

import { graphql } from '@/gql';

export const PropertyQuery = graphql(`
  query Property($id: ID!) {
    property(id: $id) {
      id
      street
      city
      state
      zipCode
      lat
      long
      createdAt
      weatherData {
        observationTime
        temperature
        feelsLike
        weatherDescriptions
        weatherIcons
        humidity
        windSpeed
        windDir
